import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"S3 模块","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/modules/s3.md","filePath":"zh-Hans/deep-dive/modules/s3.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/modules/s3.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="s3-模块" tabindex="-1">S3 模块 <a class="header-anchor" href="#s3-模块" aria-label="Permalink to “S3 模块”">​</a></h1><p>S3 模块把 Sync Engine 连接到 Amazon S3 和实现 S3 API 的对象存储服务。它注册 <code>s3</code> 远端文件系统，并使用 SDK 的请求流水线完成认证、代理路由和其他请求中间件。</p><h2 id="支持的后端" tabindex="-1">支持的后端 <a class="header-anchor" href="#支持的后端" aria-label="Permalink to “支持的后端”">​</a></h2><p>模块支持：</p><ul><li>Amazon S3</li><li>Cloudflare R2</li><li>通过 S3 兼容 API 接入的 Backblaze B2</li><li>MinIO</li><li>RustFs</li><li>阿里云 / 腾讯云对象存储</li><li>Wasabi</li><li>Rclone serve S3（仅 v1.76+，设置 <code>--directory-markers</code> 标志）</li><li>Ceph Object Gateway、DigitalOcean Spaces 以及其他 S3 兼容服务</li></ul><p>兼容性取决于服务是否实现了<a href="#所需能力与权限">所需能力与权限</a>中列出的对象操作。部分服务要求 path-style URL 而不是 virtual-hosted URL。</p><h2 id="设置与配置" tabindex="-1">设置与配置 <a class="header-anchor" href="#设置与配置" aria-label="Permalink to “设置与配置”">​</a></h2><p>安装并启用 S3 模块，然后选择 <strong>S3</strong> 作为存储后端。配置这些模块设置：</p><table tabindex="0"><thead><tr><th>设置</th><th>说明</th></tr></thead><tbody><tr><td><strong>Endpoint URL</strong></td><td>S3 服务的 HTTP(S) 端点。</td></tr><tr><td><strong>Region</strong></td><td>请求签名使用的存储桶区域。默认 <code>us-east-1</code>。</td></tr><tr><td><strong>Access key ID</strong></td><td>用于认证的访问密钥。</td></tr><tr><td><strong>Secret access key</strong></td><td>与访问密钥 ID 配对的秘密密钥。存储在 Obsidian 的钥匙串中。</td></tr><tr><td><strong>Session token</strong></td><td>可选的临时会话令牌。存储在 Obsidian 的钥匙串中。</td></tr><tr><td><strong>Bucket name</strong></td><td>存储仓库对象的存储桶。</td></tr><tr><td><strong>URL style</strong></td><td>Virtual-hosted 或 path-style 对象 URL。</td></tr><tr><td><strong>Prefix</strong></td><td>把某个子目录暴露为仓库根的键前缀。默认 <code>/</code>。</td></tr><tr><td><strong>Proxy URL</strong></td><td>可选的 S3 请求代理端点。默认关闭。</td></tr></tbody></table><p>端点、区域、访问密钥 ID、存储桶和前缀值保存为模块设置。端点和代理值必须是合法 URL。前缀按目录键规范化，<code>vault</code> 变为 <code>vault/</code>。</p><h2 id="凭据与钥匙串" tabindex="-1">凭据与钥匙串 <a class="header-anchor" href="#凭据与钥匙串" aria-label="Permalink to “凭据与钥匙串”">​</a></h2><p>访问密钥 ID 存储在模块设置中。秘密访问密钥和可选的 AWS 会话令牌通过 Obsidian 的密钥存储输入，不作为普通模块设置存储。配置了会话令牌时，S3 模块以 <code>x-amz-security-token</code> 发送它，并把该头纳入 SigV4 签名。</p><h2 id="url-风格" tabindex="-1">URL 风格 <a class="header-anchor" href="#url-风格" aria-label="Permalink to “URL 风格”">​</a></h2><p><strong>Virtual-hosted style</strong> 把存储桶放进主机名：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://bucket.s3.example.com/path/to/file.md</span></span></code></pre></div><p><strong>Path style</strong> 把存储桶放进路径：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://s3.example.com/bucket/path/to/file.md</span></span></code></pre></div><p>默认使用 virtual-hosted style。服务不提供存储桶子域名、或其 DNS 和 TLS 配置要求时，使用 path style。</p><h2 id="前缀" tabindex="-1">前缀 <a class="header-anchor" href="#前缀" aria-label="Permalink to “前缀”">​</a></h2><p>前缀选择存储桶中暴露给 Sync Engine 的部分。前缀为 <code>vault/</code> 时，本地键 <code>Notes/today.md</code> 存储为 <code>vault/Notes/today.md</code>；前缀本身对列表和文件状态隐藏。<code>/</code> 暴露存储桶根目录。</p><p>前缀是可导入的 SDK <a href="./../../development/file-system#prefixwrapper"><code>prefixWrapper</code></a>，应用于 S3 文件系统。包装器的一般行为见<a href="./../file-system-wrappers">文件系统包装器</a>。</p><h2 id="代理" tabindex="-1">代理 <a class="header-anchor" href="#代理" aria-label="Permalink to “代理”">​</a></h2><p>S3 请求需要经过 HTTP(S) 代理或网关时，启用 <strong>Proxy URL</strong>。代理替换请求主机，保留原始路径和查询。SigV4 签名发生在这个重写之前，因此代理必须把已签名的请求转发到配置的 S3 端点，并保留它的签名头。</p><h2 id="所需能力与权限" tabindex="-1">所需能力与权限 <a class="header-anchor" href="#所需能力与权限" aria-label="Permalink to “所需能力与权限”">​</a></h2><p>给 S3 身份授予与这些操作等价的权限，作用于配置的存储桶和前缀：</p><ul><li><code>ListBucket</code>：检查连接和列出对象，包括分页列表</li><li><code>GetObject</code>：下载对象、读取 range 对象数据、获取对象元数据用于文件状态</li><li><code>PutObject</code>：上传对象和文件夹标记对象</li><li><code>DeleteObject</code>：删除对象并清理被移动的对象</li><li><code>CopyObject</code>：文件移动时复制源对象</li><li>大文件流式写入所需的多部分上传权限：发起、上传分块、完成和中止多部分上传</li><li><code>DeleteObjects</code>：优化的批量删除</li></ul><p>各供应商的具体权限名称不同。策略可以把对象权限限定到配置的前缀，但存储桶列表权限也必须允许列出该前缀。</p><h2 id="实际行为" tabindex="-1">实际行为 <a class="header-anchor" href="#实际行为" aria-label="Permalink to “实际行为”">​</a></h2><ul><li>S3 只有对象，没有真实目录。<code>mkdir()</code> 创建一个以 <code>/</code> 结尾的零字节对象作为文件夹标记。</li><li>移动使用 S3 复制后删除，因为 S3 没有原生的重命名操作。</li><li>删除不存在的对象视为成功。其他服务错误会中止该操作。</li><li>文件状态优先用 <code>ETag</code>。没有时，模块以修改时间和大小作为文件 UID 的回退。</li><li><a href="./../asymmetric-storage">非对称存储</a>可以压平并锚定远端键。只在远端文件不需要保持正常文件夹结构可读时使用，并在设备之间保持该设置一致。</li></ul><h2 id="对象元数据" tabindex="-1">对象元数据 <a class="header-anchor" href="#对象元数据" aria-label="Permalink to “对象元数据”">​</a></h2><p>S3 把文件元数据存为 <code>x-amz-meta-*</code> 用户自定义头。文件 <code>meta</code> 非空时，<code>write()</code> 和多部分上传的发起会带上这些头。<code>stat()</code> 总是从 <code>HEAD</code> 响应提取 <code>x-amz-meta-*</code> 头。</p><p>S3 的 <code>ListObject</code> 不返回对象元数据，但 <code>GetObject</code> 和 <code>HeadObject</code> 返回。模块先尝试从之前缓存的 <code>GET</code> 请求中获取元数据，找不到时对每个列出的文件额外发一个 <code>HEAD</code> 请求获取元数据。</p><h2 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to “实现”">​</a></h2><h3 id="统一文件系统映射" tabindex="-1">统一文件系统映射 <a class="header-anchor" href="#统一文件系统映射" aria-label="Permalink to “统一文件系统映射”">​</a></h3><p><code>S3Fs</code> 以统一键实现 SDK 的 <code>RootFs</code> 契约：<code>/</code> 为根，<code>folder/file.md</code> 为文件，<code>folder/</code> 为文件夹。对象键按路径段做 URL 编码。配置了前缀时，S3 模块在 <code>S3Fs</code> 外应用共享的 <code>prefixWrapper</code>。</p><p>基本操作到 S3 请求的映射如下：</p><table tabindex="0"><thead><tr><th>文件系统操作</th><th>S3 操作</th></tr></thead><tbody><tr><td><code>read()</code></td><td><code>GET</code> 对象</td></tr><tr><td><code>write()</code></td><td><code>PUT</code> 对象</td></tr><tr><td><code>stat()</code></td><td><code>HEAD</code> 对象</td></tr><tr><td><code>delete()</code></td><td><code>DELETE</code> 对象</td></tr><tr><td><code>move()</code></td><td><code>CopyObject</code>，然后 <code>DELETE</code></td></tr><tr><td><code>mkdir()</code></td><td><code>PUT</code> 零字节文件夹标记</td></tr><tr><td><code>list()</code></td><td><code>ListObjectsV2</code></td></tr></tbody></table><h3 id="sigv4-中间件" tabindex="-1">SigV4 中间件 <a class="header-anchor" href="#sigv4-中间件" aria-label="Permalink to “SigV4 中间件”">​</a></h3><p>S3 是所选后端时，已注册的请求中间件用 AWS Signature Version 4 认证包装每个 S3 请求。它使用配置的访问密钥 ID、秘密访问密钥、区域和服务名 <code>s3</code>，对端点主机、方法、规范化路径、排序后的查询和请求头签名。</p><p>实现对载荷哈希发送 <code>UNSIGNED-PAYLOAD</code>，让请求抽象可以传递二进制 body 而不必缓冲它们来计算哈希。签名前存在的自定义头会纳入签名。</p><h3 id="递归列表" tabindex="-1">递归列表 <a class="header-anchor" href="#递归列表" aria-label="Permalink to “递归列表”">​</a></h3><p><code>list()</code> 使用带前缀的 S3 <code>ListObjectsV2</code>，而不是每个目录发一个请求。它跟随 <code>NextContinuationToken</code> 直到读完所有页，把每个返回的键上报给统一文件系统 reporter，并把以 <code>/</code> 结尾的键映射为文件夹。被请求的目录条目本身不出现在子项列表中。</p><h3 id="range-读取" tabindex="-1">Range 读取 <a class="header-anchor" href="#range-读取" aria-label="Permalink to “Range 读取”">​</a></h3><p><code>readStream()</code> 在请求抽象之上用 range <code>GET</code> 请求工作。它请求 2 MiB 的分块，同时在途请求最多八个，缓冲的分块最多八个，即使响应乱序到达也按文件顺序发出分块。空文件返回一个已关闭的流。</p><h3 id="多部分上传" tabindex="-1">多部分上传 <a class="header-anchor" href="#多部分上传" aria-label="Permalink to “多部分上传”">​</a></h3><p>每个 <code>writeStream()</code> 都使用 S3 多部分上传。分块通常为 5 MiB；最后一块可以更小：</p><ol><li>发起一次多部分上传。</li><li>读取 5 MiB 分块，最多三个并发上传。</li><li>按分块编号顺序用每个分块的 <code>ETag</code> 完成上传。</li></ol><p>最后一块可以小于 5 MiB。失败时，进行中的分块上传完成或 settle，然后模块尝试中止这次多部分上传。</p><h3 id="批量删除" tabindex="-1">批量删除 <a class="header-anchor" href="#批量删除" aria-label="Permalink to “批量删除”">​</a></h3><p>S3 优化器把删除原子替换为单个自定义原子，它的 <code>batchDelete()</code> 把键拆成每个最多 1000 个键的 <code>DeleteObjects</code> 请求。请求包含 XML 和 <code>Content-MD5</code> 头。服务结果按键处理：成功的键 resolve，S3 错误结果中报告的键逐个 reject。整个批量请求失败时，每个键用单独的 <code>DELETE</code> 请求重试并独立处理。</p>`,50)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};